using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Fanex.Age.Utility.DateTime
{
    public enum eConvertType
    {
        YYYYMM,
        YYYYMMDD
    }

    public static class DateTimeExtension
    {
        public static System.DateTime ToDateTime(this int value, eConvertType convertType)
        {
            var result = System.DateTime.Now;
            switch(convertType)
            {
                case eConvertType.YYYYMM:
                    int year = value / 100;
                    int month = value % 100;
                    result = new System.DateTime(year, month, 1);
                    break;
                case eConvertType.YYYYMMDD:
                    year = value / 10000;
                    int tmp = value % 10000;
                    month = tmp / 100;
                    int day = tmp % 100;
                    result = new System.DateTime(year, month, day);
                    break;
                default:
                    break;
            }
            return result;
        }

    }
}
